/**
 * MCP's public protocol path and the framework path kept for compatibility.
 *
 * Only the protocol and its OAuth/connect companions use the public alias.
 * Other framework-owned MCP management routes remain under `/_agent-native`.
 */
export declare const MCP_PUBLIC_ROUTE_PREFIX = "/mcp";
export declare const MCP_LEGACY_ROUTE_PREFIX = "/_agent-native/mcp";
export declare const MCP_ROUTE_PREFIXES: readonly ["/_agent-native/mcp", "/mcp"];
export declare function joinMcpRoute(prefix: string, suffix: string): string;
export declare function isMcpPublicPath(pathname: string): boolean;
export declare function isMcpProtocolPath(pathname: string): boolean;
